export const TYPES=['knife','gun','mine','grenade'];
export const LABELS={knife:'刀具',gun:'枪械',mine:'地雷',grenade:'手雷'};
export function fresh(){return {version:1,stage:1,completed:false,silver:150,gold:0,copper:0,bag:{knife:[1],gun:[],mine:[],grenade:[]},high:{knife:1,gun:0,mine:0,grenade:0},coreLevel:1,skin:'olive',skins:['olive'],claimed:[],kills:0};}
export function unlocks(s){return TYPES.filter((t,i)=>i===0||s.stage>i||s.bag[t].length>0);}
export function price(level,currency='silver'){return Math.ceil((currency==='gold'?90:75)*Math.pow(currency==='gold'?1.055:1.075,level-1));}
export function income(s){return s.bag.gun.reduce((sum,l)=>sum+25*Math.pow(1.065,l-1),0);}
export function merge(s,type,level){if(s.stage<4)return {ok:false,message:'第四关开放合成升级'};if(!TYPES.includes(type)||!Number.isInteger(level)||level<1||level>=500)return {ok:false,message:'已达到最高等级'};const b=s.bag[type];if(b.filter(l=>l===level).length<2)return {ok:false,message:'需要两把同等级武器'};for(let i=0;i<2;i++)b.splice(b.indexOf(level),1);b.push(level+1);b.sort((a,b)=>b-a);s.high[type]=Math.max(s.high[type],level+1);const gold=Math.ceil(12*Math.pow(1.055,level));s.gold+=gold;return {ok:true,level:level+1,gold,message:`合成成功 · Lv.${level+1} · +${gold} 金币`};}
export function buy(s,type,level,currency='silver'){if(!TYPES.includes(type)||!Number.isInteger(level)||level<1||level>500||!['silver','gold'].includes(currency))return {ok:false,message:'无效购买'};if(!unlocks(s).includes(type))return {ok:false,message:'先通关解锁这类武器'};if(currency==='silver'&&level>s.high[type])return {ok:false,message:'银币只能购买已解锁级段'};if(currency==='gold'&&s.high.gun<2)return {ok:false,message:'枪械达到二级后开启金币商店'};if(s.bag[type].length>=120)return {ok:false,message:'武器库已满，请先合成'};const p=price(level,currency);if(s[currency]<p)return {ok:false,message:currency==='gold'?'金币不足，合成升级可赚金币':'银币不足，枪械会持续产出银币'};s[currency]-=p;s.bag[type].push(level);s.bag[type].sort((a,b)=>b-a);s.high[type]=Math.max(s.high[type],level);return {ok:true,message:`已购入 ${weaponInfo(type,level).name}`};}
export function completeStage(s,stage){if(stage!==s.stage||s.completed)return {ok:false};const type=TYPES[stage];if(type){s.bag[type].push(1);s.high[type]=Math.max(s.high[type],1);}const reward=100+stage*25;s.silver+=reward;if(stage===1000)s.completed=true;else s.stage++;return {ok:true,type,reward};}
export function daily(day){return [{type:'gun',level:3},{currency:'copper',amount:5},{currency:'silver',amount:5},{currency:'gold',amount:70},null,null,{type:'gun',level:1}][day]??null;}
export function claim(s,date,day){const r=daily(day);if(!r)return {ok:false,message:'今天没有领取奖励'};if(s.claimed.includes(date))return {ok:false,message:'今天已经领取过了'};if(r.type&&s.bag[r.type].length>=120)return {ok:false,message:'武器库已满，请先合成再领取'};if(r.currency)s[r.currency]+=r.amount;else {s.bag[r.type].push(r.level);s.high[r.type]=Math.max(s.high[r.type],r.level);}s.claimed.push(date);s.claimed=s.claimed.slice(-400);return {ok:true,message:'今日奖励领取成功'};}
export function shanghaiDate(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);}
export function shanghaiDay(date=new Date()){return new Date(`${shanghaiDate(date)}T12:00:00Z`).getUTCDay();}
export function normalize(raw){const s=fresh();if(!raw||typeof raw!=='object')return s;const bounded=(n,min,max,fallback)=>Number.isFinite(n)?Math.max(min,Math.min(max,Math.floor(n))):fallback;s.stage=bounded(raw.stage,1,1000,1);s.completed=raw.completed===true&&s.stage===1000;for(const c of ['silver','gold','copper'])s[c]=Number.isFinite(raw[c])&&raw[c]>=0?Math.min(raw[c],1e100):s[c];for(const t of TYPES){s.bag[t]=Array.isArray(raw.bag?.[t])?raw.bag[t].filter(l=>Number.isInteger(l)&&l>=1&&l<=500).slice(0,120):s.bag[t];s.high[t]=Math.max(bounded(raw.high?.[t],0,500,0),...s.bag[t],0);}if(!s.bag.knife.length)s.bag.knife=[1];s.high.knife=Math.max(1,s.high.knife);s.coreLevel=bounded(raw.coreLevel,1,500,1);s.skins=Array.isArray(raw.skins)?raw.skins.filter(x=>['olive','sand','arctic','ember'].includes(x)):['olive'];if(!s.skins.includes('olive'))s.skins.push('olive');s.skin=s.skins.includes(raw.skin)?raw.skin:'olive';s.claimed=Array.isArray(raw.claimed)?raw.claimed.filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)).slice(-400):[];s.kills=bounded(raw.kills,0,1e9,0);return s;}
export function damageCore(c,amount,hps){if(c.dead||!Number.isFinite(amount)||amount<=0)return false;c.hp=Math.max(0,c.hp-amount);if(c.hp===0){if(c.layer===2)c.dead=true;else {c.layer++;c.hp=hps[c.layer];c.max=c.hp;}return true;}return false;}
export function weaponInfo(type,level){const l=Math.min(500,Math.max(1,level));if(type==='gun'){let family=l<10?'手枪':l<40?'冲锋枪':l<100?'突击步枪':l<180?'狙击枪':l<260?'巴雷特':l<340?'银色狙击枪':l<420?'黄金狙击枪':'科技脉冲枪';const sniper=l>=100&&l<420;return {name:l===1?'制式手枪':`${family} · M${String(l).padStart(3,'0')}`,family,role:sniper?'狙击手':l<10?'手枪兵':l<40?'冲锋手':l<100?'突击手':'科技兵',damage:Math.round((sniper?45:20)*Math.pow(1.035,l-1)),rate:sniper?.9:l<10?.32:l<40?.09:l<100?.13:.18,range:sniper?130:90,color:l>=340&&l<420?'#e9bd64':l>=260?'#c7d8e2':l>=420?'#79eddd':'#9cbaa5'};}
const names={knife:['普通小刀','战术军刀','合金匕首','离子战刃'],mine:['反步兵地雷','感应地雷','磁暴地雷','量子地雷'],grenade:['破片手雷','震荡手雷','电磁手雷','脉冲手雷']};const name=names[type][Math.min(3,Math.floor((l-1)/125))];return {name:l===1?name:`${name} · M${String(l).padStart(3,'0')}`,family:name,role:'近战兵',damage:Math.round((type==='knife'?48:110)*Math.pow(1.035,l-1)),rate:type==='knife'?.5:2,range:type==='knife'?4.7:16,color:'#adc3a0'};}
export function fmt(n){if(n>=1e12)return (n/1e12).toFixed(1)+'T';if(n>=1e9)return (n/1e9).toFixed(1)+'B';if(n>=1e6)return (n/1e6).toFixed(1)+'M';if(n>=1e4)return (n/1e4).toFixed(1)+'万';return Math.floor(n).toLocaleString('zh-CN');}
